import (
	"errors"
	"strconv"
)

func safeDivide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("除数不能为零")
	}
	return a / b, nil
}

func parsePositiveInt(s string) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("无法解析: %s", s)
	}
	if n <= 0 {
		return 0, errors.New("结果不是正整数")
	}
	return n, nil
}

