func sumConcurrent(nums []int) int {
	if len(nums) == 0 {
		return 0
	}
	mid := len(nums) / 2
	ch := make(chan int, 2)

	go func() {
		sum := 0
		for _, n := range nums[:mid] {
			sum += n
		}
		ch <- sum
	}()

	go func() {
		sum := 0
		for _, n := range nums[mid:] {
			sum += n
		}
		ch <- sum
	}()

	total := <-ch + <-ch
	return total
}

