func processWithWorkers(tasks []int, workerCount int) []int {
	jobs := make(chan int, len(tasks))
	results := make(chan int, len(tasks))

	// 启动worker
	for w := 0; w < workerCount; w++ {
		go func() {
			for task := range jobs {
				results <- task * 2
			}
		}()
	}

	// 发送任务
	for _, task := range tasks {
		jobs <- task
	}
	close(jobs)

	// 收集结果
	var output []int
	for i := 0; i < len(tasks); i++ {
		output = append(output, <-results)
	}
	return output
}

