import "net/http"

func processURLs(urls []string, maxConcurrent int) map[string]int {
	result := make(map[string]int)
	ch := make(chan struct{ url string; status int }, len(urls))
	sem := make(chan struct{}, maxConcurrent)

	for _, u := range urls {
		sem <- struct{}{}
		go func(url string) {
			defer func() { <-sem }()
			resp, err := http.Get(url)
			if err != nil {
				ch <- struct{ url string; status int }{url, 0}
				return
			}
			defer resp.Body.Close()
			ch <- struct{ url string; status int }{url, resp.StatusCode}
		}(u)
	}

