import "sync"

type TaskResult struct {
	TaskID string
	Result string
	Err    error
}

type SimpleScheduler struct {
	workerCount int
	tasks       chan func() TaskResult
	results     []TaskResult
	mu          sync.Mutex
	wg          sync.WaitGroup
}

func NewSimpleScheduler(workerCount int) *SimpleScheduler {
	return &SimpleScheduler{
		workerCount: workerCount,
		tasks:       make(chan func() TaskResult, 100),
	}
}

func (s *SimpleScheduler) Submit(taskID string, fn func() (string, error)) {
	s.wg.Add(1)
	s.tasks <- func() TaskResult {
		result, err := fn()
		return TaskResult{TaskID: taskID, Result: result, Err: err}
	}
}

func (s *SimpleScheduler) Start() {
	for i := 0; i < s.workerCount; i++ {
		go func() {
			for task := range s.tasks {
				r := task()
				s.mu.Lock()
				s.results = append(s.results, r)
				s.mu.Unlock()
				s.wg.Done()
			}
		}()
	}
}

func (s *SimpleScheduler) Results() []TaskResult {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.results
}

func (s *SimpleScheduler) Stop() {
	s.wg.Wait()
	close(s.tasks)
}
